fn gcd_calc(m: u32, n: u32) -> u32 {
    debug_assert!(m > 0 && n > 0);

    // Euclidean algorithm via repeated remainder.
    // Invariant: gcd(a, b) == gcd(m, n)
    // Positivity: a > 0 always; b > 0 while looping (guarded by b != 0)
    // Termination measure: b strictly decreases because 0 <= a % b < b
    let mut a = m;
    let mut b = n;

    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }

    // Since m,n > 0, the gcd is positive, and the algorithm ends with a = gcd(m,n).
    a
}